import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"How to Turn Claude Code Into a $200/Hour Automation Service in 14 Steps","description":"","frontmatter":{"url":"https://x.com/0xMoysei/status/2063858725354344815","title":"How to Turn Claude Code Into a $200/Hour Automation Service in 14 Steps","author":"Moysei","archived":"2026-06-08T00:00:00.000Z","handle":"@0xMoysei","published":"2026-06-08T00:00:00.000Z","stats":"28 likes · 4 retweets · 29 bookmarks · 1295 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-08-@0xMoysei-344815.md","filePath":"research/tweets/2026-06-08-@0xMoysei-344815.md","lastUpdated":1780990164000}'),s={name:"research/tweets/2026-06-08-@0xMoysei-344815.md"};function i(r,e,h,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-to-turn-claude-code-into-a-200-hour-automation-service-in-14-steps-—-0xmoysei" tabindex="-1">How to Turn Claude Code Into a $200/Hour Automation Service in 14 Steps — @0xMoysei <a class="header-anchor" href="#how-to-turn-claude-code-into-a-200-hour-automation-service-in-14-steps-—-0xmoysei" aria-label="Permalink to &quot;How to Turn Claude Code Into a $200/Hour Automation Service in 14 Steps — @0xMoysei&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/0xMoysei/status/2063858725354344815" target="_blank" rel="noreferrer">https://x.com/0xMoysei/status/2063858725354344815</a><strong>作者</strong>：Moysei（@0xMoysei） <strong>發布日期</strong>：2026-06-08 <strong>收錄日期</strong>：2026-06-08 <strong>類型</strong>：Twitter Article <strong>統計</strong>：28 likes · 4 retweets · 29 bookmarks · 1295 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>$20 Claude plan → repeatable client work no agency touches. A 29-year-old backend developer in Austin spent his evenings writing tests for other people&#39;s repos. He charged 40 dollars an hour, billed maybe 12 hours a week, and called it a side income. The work bored him. Claude Code did most of it faster than he could read the diff.</p><blockquote><p>Follow my profile for more like this. Then he stopped thinking of Claude as a faster keyboard and started thinking of it as the product. Every repeatable job a business pays a human to do by hand is unbilled inventory. Code review, test suites, migrations, doc generation. The work already exists. Somebody is doing it slowly. You package Claude to do it the same way every time, attach a price, and sell the output, not the hours. Here are the 14 steps that turn one terminal into a service.</p></blockquote><hr><h2 id="_1-pick-one-job-not-ai-services" tabindex="-1">1. Pick one job, not &quot;AI services&quot; <a class="header-anchor" href="#_1-pick-one-job-not-ai-services" aria-label="Permalink to &quot;1. Pick one job, not &quot;AI services&quot;&quot;">​</a></h2><h2 id="i-do-ai-automation-sells-nothing-i-write-your-missing-test-suite-in-48-hours-80-coverage-fixed-price-sells-choose-one-repeatable-task-with-a-clear-before-and-after-code-review-test-generation-a-framework-migration-api-documentation-one-job-means-one-repeatable-system-ten-jobs-means-ten-half-built-ones" tabindex="-1">&quot;I do AI automation&quot; sells nothing. &quot;I write your missing test suite in 48 hours, 80% coverage, fixed price&quot; sells. Choose one repeatable task with a clear before and after: code review, test generation, a framework migration, API documentation. One job means one repeatable system. Ten jobs means ten half-built ones. <a class="header-anchor" href="#i-do-ai-automation-sells-nothing-i-write-your-missing-test-suite-in-48-hours-80-coverage-fixed-price-sells-choose-one-repeatable-task-with-a-clear-before-and-after-code-review-test-generation-a-framework-migration-api-documentation-one-job-means-one-repeatable-system-ten-jobs-means-ten-half-built-ones" aria-label="Permalink to &quot;&quot;I do AI automation&quot; sells nothing. &quot;I write your missing test suite in 48 hours, 80% coverage, fixed price&quot; sells. Choose one repeatable task with a clear before and after: code review, test generation, a framework migration, API documentation. One job means one repeatable system. Ten jobs means ten half-built ones.&quot;">​</a></h2><h2 id="_2-write-claude-md-as-the-client-brief" tabindex="-1">2. Write CLAUDE.md as the client brief <a class="header-anchor" href="#_2-write-claude-md-as-the-client-brief" aria-label="Permalink to &quot;2. Write CLAUDE.md as the client brief&quot;">​</a></h2><h2 id="claude-forgets-everything-between-sessions-unless-you-write-it-down-drop-a-claude-md-at-the-repo-root-with-the-client-s-stack-conventions-branch-rules-and-the-definition-of-done-this-file-is-the-brief-claude-reads-on-every-run-so-the-50th-delivery-matches-the-1st-treat-it-as-the-contract-not-a-note" tabindex="-1">Claude forgets everything between sessions unless you write it down. Drop a CLAUDE.md at the repo root with the client&#39;s stack, conventions, branch rules, and the definition of done. This file is the brief Claude reads on every run, so the 50th delivery matches the 1st. Treat it as the contract, not a note. <a class="header-anchor" href="#claude-forgets-everything-between-sessions-unless-you-write-it-down-drop-a-claude-md-at-the-repo-root-with-the-client-s-stack-conventions-branch-rules-and-the-definition-of-done-this-file-is-the-brief-claude-reads-on-every-run-so-the-50th-delivery-matches-the-1st-treat-it-as-the-contract-not-a-note" aria-label="Permalink to &quot;Claude forgets everything between sessions unless you write it down. Drop a CLAUDE.md at the repo root with the client&#39;s stack, conventions, branch rules, and the definition of done. This file is the brief Claude reads on every run, so the 50th delivery matches the 1st. Treat it as the contract, not a note.&quot;">​</a></h2><h2 id="_3-run-plan-mode-before-claude-touches-code" tabindex="-1">3. Run plan mode before Claude touches code <a class="header-anchor" href="#_3-run-plan-mode-before-claude-touches-code" aria-label="Permalink to &quot;3. Run plan mode before Claude touches code&quot;">​</a></h2><h2 id="press-shift-tab-into-plan-mode-claude-reads-the-repo-and-shows-you-the-plan-before-it-writes-a-line-you-catch-the-wrong-file-the-misread-requirement-the-risky-migration-while-it-still-costs-nothing-on-client-work-an-unsupervised-first-edit-is-how-you-lose-a-repo-and-a-customer-in-the-same-afternoon" tabindex="-1">Press Shift+Tab into plan mode. Claude reads the repo and shows you the plan before it writes a line. You catch the wrong file, the misread requirement, the risky migration while it still costs nothing. On client work, an unsupervised first edit is how you lose a repo and a customer in the same afternoon. <a class="header-anchor" href="#press-shift-tab-into-plan-mode-claude-reads-the-repo-and-shows-you-the-plan-before-it-writes-a-line-you-catch-the-wrong-file-the-misread-requirement-the-risky-migration-while-it-still-costs-nothing-on-client-work-an-unsupervised-first-edit-is-how-you-lose-a-repo-and-a-customer-in-the-same-afternoon" aria-label="Permalink to &quot;Press Shift+Tab into plan mode. Claude reads the repo and shows you the plan before it writes a line. You catch the wrong file, the misread requirement, the risky migration while it still costs nothing. On client work, an unsupervised first edit is how you lose a repo and a customer in the same afternoon.&quot;">​</a></h2><h2 id="_4-build-one-subagent-per-task" tabindex="-1">4. Build one subagent per task <a class="header-anchor" href="#_4-build-one-subagent-per-task" aria-label="Permalink to &quot;4. Build one subagent per task&quot;">​</a></h2><p>[圖 1] Make .claude/agents/code-reviewer.md. Three lines of frontmatter set its name, its tools, and its model:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: code-reviewer</span></span>
<span class="line"><span>tools: Read, Grep, Bash</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>You review pull requests for security and style.</span></span>
<span class="line"><span>Flag every issue with file and line. Suggest the fix.</span></span></code></pre></div><h2 id="add-test-writer-md-migrator-md-doc-gen-md-each-agent-runs-in-its-own-context-so-the-reviewer-never-gets-confused-by-the-test-writer-s-work-five-specialists-beat-one-overloaded-chat" tabindex="-1">Add test-writer.md, migrator.md, doc-gen.md. Each agent runs in its own context, so the reviewer never gets confused by the test writer&#39;s work. Five specialists beat one overloaded chat. <a class="header-anchor" href="#add-test-writer-md-migrator-md-doc-gen-md-each-agent-runs-in-its-own-context-so-the-reviewer-never-gets-confused-by-the-test-writer-s-work-five-specialists-beat-one-overloaded-chat" aria-label="Permalink to &quot;Add test-writer.md, migrator.md, doc-gen.md. Each agent runs in its own context, so the reviewer never gets confused by the test writer&#39;s work. Five specialists beat one overloaded chat.&quot;">​</a></h2><h2 id="_5-package-the-job-into-slash-commands" tabindex="-1">5. Package the job into slash commands <a class="header-anchor" href="#_5-package-the-job-into-slash-commands" aria-label="Permalink to &quot;5. Package the job into slash commands&quot;">​</a></h2><h2 id="a-client-engagement-is-the-same-five-moves-every-time-wrap-them-in-intake-and-deliver-commands-stored-in-claude-commands-one-line-spins-up-the-whole-flow-read-the-brief-route-to-the-right-agent-run-the-checks-format-the-output-you-stop-retyping-prompts-and-start-running-a-procedure" tabindex="-1">A client engagement is the same five moves every time. Wrap them in /intake and /deliver commands stored in .claude/commands/. One line spins up the whole flow: read the brief, route to the right agent, run the checks, format the output. You stop retyping prompts and start running a procedure. <a class="header-anchor" href="#a-client-engagement-is-the-same-five-moves-every-time-wrap-them-in-intake-and-deliver-commands-stored-in-claude-commands-one-line-spins-up-the-whole-flow-read-the-brief-route-to-the-right-agent-run-the-checks-format-the-output-you-stop-retyping-prompts-and-start-running-a-procedure" aria-label="Permalink to &quot;A client engagement is the same five moves every time. Wrap them in /intake and /deliver commands stored in .claude/commands/. One line spins up the whole flow: read the brief, route to the right agent, run the checks, format the output. You stop retyping prompts and start running a procedure.&quot;">​</a></h2><h2 id="_6-put-hooks-at-the-qa-gate" tabindex="-1">6. Put hooks at the QA gate <a class="header-anchor" href="#_6-put-hooks-at-the-qa-gate" aria-label="Permalink to &quot;6. Put hooks at the QA gate&quot;">​</a></h2><h2 id="圖-2-a-posttooluse-hook-runs-your-linter-and-test-suite-automatically-after-claude-edits-a-file-nothing-reaches-the-client-until-it-passes-the-hook-is-the-difference-between-i-think-it-works-and-the-tests-are-green-here-is-the-log-you-sell-the-second-one" tabindex="-1">[圖 2] A PostToolUse hook runs your linter and test suite automatically after Claude edits a file. Nothing reaches the client until it passes. The hook is the difference between &quot;I think it works&quot; and &quot;the tests are green, here is the log.&quot; You sell the second one. <a class="header-anchor" href="#圖-2-a-posttooluse-hook-runs-your-linter-and-test-suite-automatically-after-claude-edits-a-file-nothing-reaches-the-client-until-it-passes-the-hook-is-the-difference-between-i-think-it-works-and-the-tests-are-green-here-is-the-log-you-sell-the-second-one" aria-label="Permalink to &quot;[圖 2]
A PostToolUse hook runs your linter and test suite automatically after Claude edits a file. Nothing reaches the client until it passes. The hook is the difference between &quot;I think it works&quot; and &quot;the tests are green, here is the log.&quot; You sell the second one.&quot;">​</a></h2><h2 id="_7-connect-client-tools-through-mcp" tabindex="-1">7. Connect client tools through MCP <a class="header-anchor" href="#_7-connect-client-tools-through-mcp" aria-label="Permalink to &quot;7. Connect client tools through MCP&quot;">​</a></h2><h2 id="claude-code-reads-your-client-s-github-a-read-only-database-their-notion-through-mcp-servers-you-add-per-project-the-agent-works-against-real-context-instead-of-pasted-snippets-give-it-read-only-access-to-production-and-write-access-only-to-a-working-branch" tabindex="-1">Claude Code reads your client&#39;s GitHub, a read-only database, their Notion, through MCP servers you add per project. The agent works against real context instead of pasted snippets. Give it read-only access to production and write access only to a working branch. <a class="header-anchor" href="#claude-code-reads-your-client-s-github-a-read-only-database-their-notion-through-mcp-servers-you-add-per-project-the-agent-works-against-real-context-instead-of-pasted-snippets-give-it-read-only-access-to-production-and-write-access-only-to-a-working-branch" aria-label="Permalink to &quot;Claude Code reads your client&#39;s GitHub, a read-only database, their Notion, through MCP servers you add per project. The agent works against real context instead of pasted snippets. Give it read-only access to production and write access only to a working branch.&quot;">​</a></h2><h2 id="_8-block-secrets-with-deny-rules-plus-a-hook" tabindex="-1">8. Block secrets with deny rules plus a hook <a class="header-anchor" href="#_8-block-secrets-with-deny-rules-plus-a-hook" aria-label="Permalink to &quot;8. Block secrets with deny rules plus a hook&quot;">​</a></h2><h2 id="圖-3-in-settings-json-deny-reads-on-env-ssh-and-secrets-json-know-the-catch-anthropic-calls-read-deny-a-best-effort-control-and-reported-bugs-show-it-can-miss-files-at-session-start-so-back-it-with-a-pretooluse-hook-that-checks-the-path-and-hard-blocks-the-call-before-it-runs-the-deny-rule-is-the-policy-the-hook-is-the-enforcement-a-client-hands-you-a-repo-because-they-trust-that-boundary-and-keys-that-never-enter-context-never-end-up-in-a-transcript" tabindex="-1">[圖 3] In settings.json, deny reads on .env, ~/.ssh/**, and secrets.json. Know the catch: Anthropic calls Read deny a best-effort control, and reported bugs show it can miss files at session start. So back it with a PreToolUse hook that checks the path and hard-blocks the call before it runs. The deny rule is the policy, the hook is the enforcement. A client hands you a repo because they trust that boundary, and keys that never enter context never end up in a transcript. <a class="header-anchor" href="#圖-3-in-settings-json-deny-reads-on-env-ssh-and-secrets-json-know-the-catch-anthropic-calls-read-deny-a-best-effort-control-and-reported-bugs-show-it-can-miss-files-at-session-start-so-back-it-with-a-pretooluse-hook-that-checks-the-path-and-hard-blocks-the-call-before-it-runs-the-deny-rule-is-the-policy-the-hook-is-the-enforcement-a-client-hands-you-a-repo-because-they-trust-that-boundary-and-keys-that-never-enter-context-never-end-up-in-a-transcript" aria-label="Permalink to &quot;[圖 3]
In settings.json, deny reads on .env, ~/.ssh/**, and secrets.json. Know the catch: Anthropic calls Read deny a best-effort control, and reported bugs show it can miss files at session start. So back it with a PreToolUse hook that checks the path and hard-blocks the call before it runs. The deny rule is the policy, the hook is the enforcement. A client hands you a repo because they trust that boundary, and keys that never enter context never end up in a transcript.&quot;">​</a></h2><h2 id="_9-cron-the-overnight-work" tabindex="-1">9. Cron the overnight work <a class="header-anchor" href="#_9-cron-the-overnight-work" aria-label="Permalink to &quot;9. Cron the overnight work&quot;">​</a></h2><h2 id="圖-4-a-review-queue-does-not-need-you-awake-a-scheduled-job-runs-the-reviewer-agent-at-2-a-m-against-the-day-s-open-prs-and-leaves-comments-by-morning-the-client-wakes-up-to-finished-work-you-wake-up-to-an-invoice-line" tabindex="-1">[圖 4] A review queue does not need you awake. A scheduled job runs the reviewer agent at 2 a.m. against the day&#39;s open PRs and leaves comments by morning. The client wakes up to finished work. You wake up to an invoice line. <a class="header-anchor" href="#圖-4-a-review-queue-does-not-need-you-awake-a-scheduled-job-runs-the-reviewer-agent-at-2-a-m-against-the-day-s-open-prs-and-leaves-comments-by-morning-the-client-wakes-up-to-finished-work-you-wake-up-to-an-invoice-line" aria-label="Permalink to &quot;[圖 4]
A review queue does not need you awake. A scheduled job runs the reviewer agent at 2 a.m. against the day&#39;s open PRs and leaves comments by morning. The client wakes up to finished work. You wake up to an invoice line.&quot;">​</a></h2><h2 id="_10-make-the-output-template-the-deliverable" tabindex="-1">10. Make the output template the deliverable <a class="header-anchor" href="#_10-make-the-output-template-the-deliverable" aria-label="Permalink to &quot;10. Make the output template the deliverable&quot;">​</a></h2><h2 id="same-format-every-client-every-time-a-summary-the-findings-table-the-diffs-the-test-log-save-it-as-a-template-the-deliver-command-fills-a-consistent-artifact-is-what-a-buyer-remembers-and-refers-surprise-formatting-reads-as-amateur" tabindex="-1">Same format, every client, every time: a summary, the findings table, the diffs, the test log. Save it as a template the /deliver command fills. A consistent artifact is what a buyer remembers and refers. Surprise formatting reads as amateur. <a class="header-anchor" href="#same-format-every-client-every-time-a-summary-the-findings-table-the-diffs-the-test-log-save-it-as-a-template-the-deliver-command-fills-a-consistent-artifact-is-what-a-buyer-remembers-and-refers-surprise-formatting-reads-as-amateur" aria-label="Permalink to &quot;Same format, every client, every time: a summary, the findings table, the diffs, the test log. Save it as a template the /deliver command fills. A consistent artifact is what a buyer remembers and refers. Surprise formatting reads as amateur.&quot;">​</a></h2><h2 id="_11-log-every-command" tabindex="-1">11. Log every command <a class="header-anchor" href="#_11-log-every-command" aria-label="Permalink to &quot;11. Log every command&quot;">​</a></h2><h2 id="pipe-each-agent-action-to-a-dated-log-file-when-a-client-asks-what-happened-to-a-file-you-show-the-trail-an-audit-log-is-what-lets-a-business-trust-an-ai-with-their-codebase-it-also-covers-you-when-something-breaks-and-they-want-to-know-whose-change-did-it" tabindex="-1">Pipe each agent action to a dated log file. When a client asks what happened to a file, you show the trail. An audit log is what lets a business trust an AI with their codebase. It also covers you when something breaks and they want to know whose change did it. <a class="header-anchor" href="#pipe-each-agent-action-to-a-dated-log-file-when-a-client-asks-what-happened-to-a-file-you-show-the-trail-an-audit-log-is-what-lets-a-business-trust-an-ai-with-their-codebase-it-also-covers-you-when-something-breaks-and-they-want-to-know-whose-change-did-it" aria-label="Permalink to &quot;Pipe each agent action to a dated log file. When a client asks what happened to a file, you show the trail. An audit log is what lets a business trust an AI with their codebase. It also covers you when something breaks and they want to know whose change did it.&quot;">​</a></h2><h2 id="_12-price-the-task-not-the-hour" tabindex="-1">12. Price the task, not the hour <a class="header-anchor" href="#_12-price-the-task-not-the-hour" aria-label="Permalink to &quot;12. Price the task, not the hour&quot;">​</a></h2><h2 id="圖-5-the-200-dollar-an-hour-figure-is-a-ceiling-you-back-into-not-a-rate-you-announce-quote-the-job-600-dollars-for-a-test-suite-1-200-for-a-migration-if-your-system-finishes-a-1-200-dollar-migration-in-6-hours-your-effective-rate-is-200-the-client-buys-a-fixed-outcome-and-a-fixed-price-you-keep-the-speed-you-built" tabindex="-1">[圖 5] The 200-dollar-an-hour figure is a ceiling you back into, not a rate you announce. Quote the job: 600 dollars for a test suite, 1,200 for a migration. If your system finishes a 1,200-dollar migration in 6 hours, your effective rate is 200. The client buys a fixed outcome and a fixed price. You keep the speed you built. <a class="header-anchor" href="#圖-5-the-200-dollar-an-hour-figure-is-a-ceiling-you-back-into-not-a-rate-you-announce-quote-the-job-600-dollars-for-a-test-suite-1-200-for-a-migration-if-your-system-finishes-a-1-200-dollar-migration-in-6-hours-your-effective-rate-is-200-the-client-buys-a-fixed-outcome-and-a-fixed-price-you-keep-the-speed-you-built" aria-label="Permalink to &quot;[圖 5]
The 200-dollar-an-hour figure is a ceiling you back into, not a rate you announce. Quote the job: 600 dollars for a test suite, 1,200 for a migration. If your system finishes a 1,200-dollar migration in 6 hours, your effective rate is 200. The client buys a fixed outcome and a fixed price. You keep the speed you built.&quot;">​</a></h2><h2 id="_13-attach-the-invoice-to-the-delivery" tabindex="-1">13. Attach the invoice to the delivery <a class="header-anchor" href="#_13-attach-the-invoice-to-the-delivery" aria-label="Permalink to &quot;13. Attach the invoice to the delivery&quot;">​</a></h2><h2 id="put-a-stripe-payment-link-in-the-same-message-as-the-deliverable-while-the-value-is-fresh-no-separate-invoicing-ritual-a-week-later-the-client-sees-the-finished-test-suite-and-the-pay-button-in-one-place-friction-removed-is-money-kept" tabindex="-1">Put a Stripe payment link in the same message as the deliverable, while the value is fresh. No separate invoicing ritual a week later. The client sees the finished test suite and the pay button in one place. Friction removed is money kept. <a class="header-anchor" href="#put-a-stripe-payment-link-in-the-same-message-as-the-deliverable-while-the-value-is-fresh-no-separate-invoicing-ritual-a-week-later-the-client-sees-the-finished-test-suite-and-the-pay-button-in-one-place-friction-removed-is-money-kept" aria-label="Permalink to &quot;Put a Stripe payment link in the same message as the deliverable, while the value is fresh. No separate invoicing ritual a week later. The client sees the finished test suite and the pay button in one place. Friction removed is money kept.&quot;">​</a></h2><h2 id="_14-run-clients-in-parallel-and-productize-the-stack" tabindex="-1">14. Run clients in parallel and productize the stack <a class="header-anchor" href="#_14-run-clients-in-parallel-and-productize-the-stack" aria-label="Permalink to &quot;14. Run clients in parallel and productize the stack&quot;">​</a></h2><h2 id="the-whole-setup-lives-in-one-repo-agents-commands-hooks-templates-deny-rules-clone-it-per-client-swap-the-claude-md-and-you-onboard-in-minutes-subagents-run-several-jobs-at-once-so-9-clients-feel-like-2-at-that-point-you-are-not-freelancing-you-are-running-a-service-with-one-employee-who-never-sleeps" tabindex="-1">The whole setup lives in one repo: agents, commands, hooks, templates, deny rules. Clone it per client, swap the CLAUDE.md, and you onboard in minutes. Subagents run several jobs at once, so 9 clients feel like 2. At that point you are not freelancing. You are running a service with one employee who never sleeps. <a class="header-anchor" href="#the-whole-setup-lives-in-one-repo-agents-commands-hooks-templates-deny-rules-clone-it-per-client-swap-the-claude-md-and-you-onboard-in-minutes-subagents-run-several-jobs-at-once-so-9-clients-feel-like-2-at-that-point-you-are-not-freelancing-you-are-running-a-service-with-one-employee-who-never-sleeps" aria-label="Permalink to &quot;The whole setup lives in one repo: agents, commands, hooks, templates, deny rules. Clone it per client, swap the CLAUDE.md, and you onboard in minutes. Subagents run several jobs at once, so 9 clients feel like 2. At that point you are not freelancing. You are running a service with one employee who never sleeps.&quot;">​</a></h2><blockquote><p>A clean starter repo with the agents, commands, and hooks from these 14 steps is in the community on my profile. Clone it, point it at one real task, and bill the first job this week. The work was always there. You were doing it for free.</p></blockquote><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：14 步驟將 Claude Code 打造成固定價格自動化外包服務，核心是 CLAUDE.md/subagents/hooks/MCP 打包成可複製的客戶交付流程。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>CLAUDE.md 作為客戶簡報</strong>：持久化 context，第 50 次交付與第 1 次一致</li><li><strong>Plan mode 先審核再動手</strong>：防止未監督首次編輯損壞客戶 repo</li><li><strong>Subagent per task</strong>：code-reviewer/test-writer/migrator/doc-gen 各自隔離 context</li><li><strong>PostToolUse hook 作 QA 閘門</strong>：自動跑 lint + test，通過才交付</li><li><strong>固定價格定價</strong>：賣成果（$600 test suite / $1200 migration），有效時薪 $200/hr 是倒推出來的</li><li><strong>秘密雙層防護</strong>：settings.json deny rules + PreToolUse hook（deny 是政策，hook 是執法）</li></ul><h3 id="關鍵工具-數字" tabindex="-1">關鍵工具/數字 <a class="header-anchor" href="#關鍵工具-數字" aria-label="Permalink to &quot;關鍵工具/數字&quot;">​</a></h3><ul><li>$200/hr 有效時薪（固定定價倒推）</li><li><code>.claude/agents/{name}.md</code> subagent frontmatter（name/tools/model 三欄）</li><li>PostToolUse hook（自動 linter/test）</li><li>PreToolUse hook（阻擋 .env/.ssh 敏感路徑）</li><li>settings.json deny rules</li><li><code>/intake</code>、<code>/deliver</code> slash commands（.claude/commands/）</li><li>MCP（GitHub/read-only DB/Notion）</li><li>28 likes / 1,295 views（低傳播，帳號 379 followers）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>可信度存疑</strong>：帳號僅 379 followers，低互動數據；「$200/hr」標題具行銷誇大特徵，無實際案例驗證</li><li><strong>技術深度偏淺</strong>：14 步驟各為 2-3 段提綱，hooks 腳本/MCP 設定細節缺失，更像目錄而非完整指南</li><li><strong>安全建議有實際價值</strong>：deny rules + PreToolUse hook double-layer 符合最佳實踐，是文章中最具體可行的技術貢獻</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>方向正確（CLAUDE.md/subagents/hooks），但缺細節；14步驟需自行補完</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>外包服務打包角度新鮮，但技術均是已知功能重新排列</td></tr><tr><td>C. 證據品質 (20%)</td><td>3/10</td><td>低粉絲帳號、無實際案例、$200/hr 無驗證；開篇故事是行銷敘事</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>各步驟概念正確但淺；hooks/MCP 僅點到為止，無可複製腳本</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>框架適用所有可重複代碼任務外包，但實際可行性未驗證</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.5/10</strong></td><td>7×0.3+5×0.2+3×0.2+5×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip（僅歸檔） <strong>理由</strong>：總分 5.5 未達門檻；技術提綱正確但缺深度，來源可信度低，不建議直接整合至 workspace</p>`,51)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
